				\begin{document}$$\begin{gathered} \Delta \sigma_{{{\mathrm{th}}}} = \frac{{\Delta K_{{{\mathrm{th}}}} }}{{F_{W} \sqrt {\pi \left( {a \times 10^{ - 6} + \frac{1}{\pi }\left( {\frac{{\Delta K_{{{\mathrm{th}}}} }}{{F_{W} \times (2 \times (318 + 153e^{{\left( { - d/64} \right)}} ))}}} \right)^{2} } \right)} }} \hfill \\ d \le 210 \hfill \\ \end{gathered}$$\end{document}
